		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Operator." );

			StringBuilder msg = new StringBuilder( "Failed to update a Operator : " );        
			Operator entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Operator." );

				// for use later on...
				thePrimaryKey = entity.getOperatorId();

				OperatorService proxy = OperatorService.getOperatorInstance();            
				proxy.updateOperator( entity );   

				LOGGER.info( "-- Successfully saved Operator - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

